#include "mgt/batch_norm_training.hpp"
#include "mgt/config.hpp"
#include <cstdlib>
int main(){mgt::BatchNormTrainingPlan p{};using C=mgt::P888TrainingContract;constexpr std::uint32_t ph2=224;if(mgt::BuildBatchNormTrainingPlan(C::kHidden1,C::kHidden2,C::kHidden1,ph2,C::kResidualBlocks,12500,&p)!=mgt::Status::kOk)return 1;const std::uint64_t logical=C::kHidden1+33ULL*C::kHidden2,storage=C::kHidden1+33ULL*ph2;if(p.sites.size()!=C::kBatchNormSites||p.logical_feature_count!=logical||p.storage_feature_count!=storage||p.trainable_count!=2*logical||p.running_count!=2*logical||p.normalized_count!=12500ULL*storage||p.mean_offset!=p.normalized_count||p.inv_std_offset!=p.mean_offset+logical||p.reduction_offset!=p.inv_std_offset+logical||p.reduction_count!=2ULL*C::kHidden1||p.workspace_floats!=p.reduction_offset+p.reduction_count)return 1;if(p.sites[1].logical_features!=C::kHidden2||p.sites[1].physical_stride!=ph2||p.sites[2].normalized_offset!=12500ULL*(C::kHidden1+ph2))return 1;auto s=mgt::InitializeBatchNormTrainingState(p);if(s.affine.size()!=p.trainable_count||s.running.size()!=p.running_count||s.adam_m.size()!=p.trainable_count||s.adam_v.size()!=p.trainable_count)return 1;for(std::uint64_t i=0;i<logical;i++)if(s.affine[i]!=1||s.affine[logical+i]!=0||s.running[i]!=0||s.running[logical+i]!=1||s.adam_m[i]!=0||s.adam_v[i]!=0)return 1;return 0;}